TRACK_A = (
    Entry("Exclusive branch / case / φ join", "have", "Python <code>if</code> and <code>match</code> already read as an exclusive Branch region with a join. LabVIEW Case, Blueprint Branch/Switch, and Simulink If/Merge confirm the settled reading grammar; they do not justify a new palette node.", (("NI Case Structures", "https://www.ni.com/docs/en-US/bundle/labview/page/case-structures-executing-a-section-of-code-based-on-input-values.html"), ("Epic Flow Control", "https://dev.epicgames.com/documentation/en-us/unreal-engine/flow-control-in-unreal-engine"), ("MathWorks If", "https://www.mathworks.com/help/simulink/slref/if.html")), (Current("branch-region-3-wired.png", "SystemSketch Branch region with visible paths and join", "src/branch/branchModel.ts"),)),
    Entry("Loop-carried previous value / delayed edge", "have", "A loop-carried value already has a distinct <code>z⁻¹</code> treatment, separating a prior iteration from same-iteration data. LabVIEW Feedback and Simulink Unit Delay corroborate that reading while their simulation-time rules remain outside ordinary Python.", (("NI Feedback Node", "https://www.ni.com/docs/en-US/bundle/labview-api-ref/page/functions/feedback-node.html"), ("MathWorks Unit Delay", "https://www.mathworks.com/help/simulink/slref/unitdelay.html")), (Current("loop-region-acceptance.png", "SystemSketch Loop region with a loop-carried value", "src/loop/loopModel.ts"),)),
    Entry("Named record-field projection / Split", "have", "The stock <b>Split</b> preset already projects a resolved record into name-stable accessor rows. This is SystemSketch's existing equivalent of Unbundle By Name, Split Struct Pin, and Bus Selector; the earlier report incorrectly called it missing.", (("NI Unbundle By Name", "https://www.ni.com/docs/en-US/bundle/labview-api-ref/page/functions/unbundle-by-name.html"), ("Epic Struct Variables", "https://dev.epicgames.com/documentation/en-us/unreal-engine/struct-variables-in-blueprints?application_version=4.27"), ("MathWorks Bus Selector", "https://www.mathworks.com/help/simulink/slref/busselector.html")), (Current("unknown-projection-picker-open.png", "Stock Split preset in the Block picker", "src/blocks/connections/blockPicker.ts"), Current("unknown-projection-accessors.png", "Split with named accessor rows and propagated types", "src/blocks/unknownAndProjection.test.ts"))),
    Entry("Ordinary data paths for event, error, state, and configuration values", "have", "These meanings do not require another transport. A typed value can already travel through an ordinary arrow or tunnel to a handler, bus, or component; the missing improvement is a semantic role label on that same path, not a new event dispatcher or exception rail.", (("NI Handling Errors", "https://www.ni.com/docs/en-US/bundle/labview/page/handling-errors.html"), ("MathWorks Signal Types", "https://www.mathworks.com/help/simulink/ug/signal-types.html")), (Current("edge-tunnel-inspector-live-2026-09-02.png", "SystemSketch ordinary edge and tunnel presentation", "src/blocks/connections/connectionModel.ts"),)),
    Entry("Normal return versus derived mutation effect", "have", "A port declared mutating already derives a top-edge effect exit, preventing an in-place-looking write from reading like an ordinary returned value. This borrows the reader benefit of Blueprint pure/impure distinction without importing pervasive execution cables.", (("Epic Functions", "https://dev.epicgames.com/documentation/en-us/unreal-engine/functions?application_version=4.27"),), (Current("effect-ports-3-wired-2026-09-03.png", "SystemSketch top-edge effect exit on a mutating call", "src/blocks/effectPorts.ts"),)),
    Entry("Named partial record update / Set attributes", "useful", "Bundle By Name, Set Members in Struct, and Bus Assignment converge on the same readable operation: update selected named members while preserving the rest. Zach has approved shipping the already-designed batched <code>setattr</code> shape as a stock Block with ordinary record data in and out.", (("NI Bundle By Name", "https://www.ni.com/docs/en-US/bundle/labview-api-ref/page/functions/bundle-by-name.html"), ("Epic Struct Variables", "https://dev.epicgames.com/documentation/en-us/unreal-engine/struct-variables-in-blueprints?application_version=4.27"), ("MathWorks Bus Assignment", "https://www.mathworks.com/help/simulink/slref/busassignment.html")), evidence=(LV_BUNDLE, BP_SET, SL_ASSIGN), proposal=PROPOSALS["update"], lift="<b>Lift · medium.</b> The drawing and source intent already exist. Shipping still needs a stock preset, named-row editing, source-projection rules, and regression coverage for batched writes and preserved members."),
    Entry("Conditional value selection / Select", "useful", "LabVIEW Select and Simulink Switch make a value choice distinct from an effectful branch. Epic's RigVM API documents the same <code>Condition</code> / <code>If True</code> / <code>If False</code> contract, but its reference page does not publish a graph screenshot, so this row does not substitute a documentation table for actual tool UI. Zach has approved a stock Select Block for Python's <code>true_value if condition else false_value</code>: two value inputs, one Boolean control value, and one ordinary output.", (("NI Select", "https://www.ni.com/docs/en-US/bundle/labview-api-ref/page/functions/select.html"), ("Epic Make Select", "https://dev.epicgames.com/documentation/en-us/unreal-engine/BlueprintAPI/Utilities/Struct/MakeSelect"), ("MathWorks Switch", "https://www.mathworks.com/help/simulink/slref/switch.html")), evidence=(Evidence("gap-labview-select-2026-09-03.png", "LabVIEW Select function", "NI · Select", "https://www.ni.com/docs/en-US/bundle/labview-api-ref/page/functions/select.html"), Evidence("gap-simulink-switch-2026-09-03.png", "Simulink Switch boolean-control example", "MathWorks · Switch", "https://www.mathworks.com/help/simulink/slref/switch.html")), proposal=PROPOSALS["select"], lift="<b>Lift · low to medium.</b> Add the stock preset and source projection, keep its output on the data plane, and test that it remains visually and semantically distinct from the Branch region."),
    Entry("Analyzer-recognised asynchronous data path", "useful", "LabVIEW's asynchronous channel wire and Simulink's dash-dot function-call control signals show that delivery semantics can deserve a redundant cable cue. In SystemSketch this remains a direct data path: use the existing <b>dashed</b> async edge only when source proves asynchronous delivery, with no invented queue box, junction, or ownership topology. In the MathWorks example E1/E2 are periodic function-call controls and E3 is interrupt-driven—not generic asynchronous payload cables.", (("NI Using Wires", "https://www.ni.com/docs/en-US/bundle/labview/page/using-wires-to-link-block-diagram-objects.html"), ("MathWorks Model Reference Function-Call", "https://www.mathworks.com/help/simulink/slref/model-reference-function-call.html"), ("MathWorks Signal Types", "https://www.mathworks.com/help/simulink/ug/signal-types.html")), evidence=(Evidence("gap-labview-async-channel-2026-09-03.png", "LabVIEW asynchronous channel wire", "NI · Using Wires", "https://www.ni.com/docs/en-US/bundle/labview/page/using-wires-to-link-block-diagram-objects.html"), Evidence("gap-simulink-function-call-2026-09-03.png", "Simulink periodic and interrupt-driven function-call controls", "MathWorks · Model Reference Function-Call", "https://www.mathworks.com/help/simulink/slref/model-reference-function-call.html")), proposal=PROPOSALS["async"], lift="<b>Lift · medium to high.</b> The cable style already ships. The real work is a conservative source fact for async delivery and an inspector explanation that does not claim buffering, ordering, or queue ownership."),
    Entry("Clock / Trigger stock source", "useful", "A visible Clock or Trigger source makes a real periodic or external activation legible without hiding scheduling inside a downstream Block. It emits an ordinary typed trigger/event/control value; the rate or source is explicit, and adapters may map that value to Python, ROS, or event-loop timing.", (("NI Timing and Synchronization", "https://www.ni.com/en/shop/labview/timing-and-synchronization-in-ni-labview.html"), ("MathWorks Function-Call Generator", "https://www.mathworks.com/help/simulink/slref/functioncallgenerator.html"), ("MathWorks Model Reference Function-Call", "https://www.mathworks.com/help/simulink/slref/model-reference-function-call.html")), evidence=(Evidence("gap-labview-timed-loop-2026-09-04.png", "LabVIEW Timed Loop with explicit timing terminals", "NI · Timing and Synchronization", "https://www.ni.com/en/shop/labview/timing-and-synchronization-in-ni-labview.html"), Evidence("gap-simulink-function-call-2026-09-03.png", "Simulink clocked and interrupt-driven function calls", "MathWorks · Model Reference Function-Call", "https://www.mathworks.com/help/simulink/slref/model-reference-function-call.html")), proposal=PROPOSALS["clock"], lift="<b>Lift · medium.</b> Define a stock source, rate/source fields, and explicit runtime-adapter contract. It must never imply that merely drawing a 10 Hz block creates a hidden scheduler."),
    Entry("Explicit exception / Cast Failed / railway outcome rail", "skip", "Exceptions, narrowing failures such as Blueprint <code>Cast Failed</code>, and railway-style outcomes are normal data in SystemSketch. Route an Error-tagged value through ordinary arrows or tunnels to a shared handler or bus; do not reuse the top-edge mutation-effect grammar or put a special failure pin on every call.", (("NI Handling Errors", "https://www.ni.com/docs/en-US/bundle/labview/page/handling-errors.html"), ("Epic Cast To", "https://dev.epicgames.com/documentation/en-us/unreal-engine/BlueprintAPI/Utilities/Casting/CastToGameInstance"))),
    Entry("Bespoke event-dispatch relation", "skip", "An event is a value—often a record with type, time, payload, or timeout—and follows normal dataflow. A preset Event tag can explain its role without adding registration cables, dispatcher nodes, or a second execution model.", (("NI Event Structure", "https://www.ni.com/docs/en-US/bundle/labview-api-ref/page/structures/event-structure.html"), ("Epic Bind and Unbind Events", "https://dev.epicgames.com/documentation/en-us/unreal-engine/binding-and-unbinding-events-in-unreal-engine?lang=en-US"), ("MathWorks Stateflow Events", "https://www.mathworks.com/help/stateflow/ug/control-state-execution-by-using-events.html"))),
    Entry("Derived state-machine or statechart overlay", "skip", "State/configuration values and their real dataflow already express the useful model. Do not derive a separate statechart from ordinary enum-and-conditional code; Stateflow remains reference evidence, not a requested SystemSketch layer.", (("MathWorks Stateflow States", "https://www.mathworks.com/help/stateflow/ug/states.html"),)),
    Entry("Arithmetic, comparisons, collections, and signal-routing palettes", "skip", "LabVIEW numeric/Boolean, Blueprint Array/Map/Set, and Simulink math/routing palettes are authoring conveniences. Python already states operators, calls, unpacking, indexing, and collection construction; special glyph libraries would add a second language rather than a renderer fact.", (("NI Block Diagram Explained", "https://www.ni.com/en/support/documentation/supplemental/08/labview-block-diagram-explained.html"), ("Epic Blueprint Palette", "https://dev.epicgames.com/documentation/unreal-engine/palette-in-the-bleprints-visual-scripting-editor-for-unreal-engine?lang=en-US"), ("MathWorks Library Browser", "https://www.mathworks.com/help/simulink/slref/librarybrowser.html"))),
    Entry("Implicit Sequence, Gate, DoOnce, Delay, and scheduler controls", "skip", "These encode tool-specific pulses, latches, wall-clock policy, or simulator scheduling without a source-owned value. Preserve explicit Python order. This exclusion does not apply to the proposed visible Clock/Trigger source above.", (("Epic Flow Control", "https://dev.epicgames.com/documentation/en-us/unreal-engine/flow-control-in-unreal-engine"),)),
    Entry("Formula/MATLAB Function, macros, and authorable interface subgraphs", "skip", "These are text escape hatches or reusable graph-authoring systems in palette tools. SystemSketch already takes the stronger source-first position: Python is canonical and linked definitions are the presentation seam.", (("MathWorks MATLAB Function", "https://www.mathworks.com/help/simulink/slref/matlabfunction.html"), ("Epic Blueprint Macros", "https://dev.epicgames.com/documentation/en-us/unreal-engine/macros-in-unreal-engine"))),
    Entry("Property/Invoke, variants, construction/spawn, hardware, and runtime palettes", "skip", "Framework APIs, Unreal lifecycle nodes, LabVIEW hardware controls, and Simulink time/sample-rate configuration belong to their host runtimes. They are ordinary Python calls or deliberately outside a static Python renderer.", (("Epic Blueprint Class UI", "https://dev.epicgames.com/documentation/unreal-engine/blueprints-visual-scripting-user-interface-for-blueprint-classes-in-unreal-engine"), ("NI Block Diagram Explained", "https://www.ni.com/en/support/documentation/supplemental/08/labview-block-diagram-explained.html"), ("MathWorks Simulink Editor", "https://www.mathworks.com/help/simulink/slref/simulinkeditor.html"))),
    Entry("State history junctions and visual variant pickers", "skip", "History restoration and variant activation have specialised runtime contracts but no dependable generic Python syntax. Do not infer hidden statechart memory or add a canvas-side configuration picker.", (("MathWorks History Junctions", "https://www.mathworks.com/help/stateflow/ug/history-junctions.html"), ("MathWorks Variant Manager", "https://www.mathworks.com/help/simulink/gui/variant-manager-overview.html"))),
)


TRACK_B = (
    Entry("Simple / Port / Expanded presentation", "have", "Compactness is already reversible presentation: Simple, Port, and Expanded views change density without deleting source-derived relationships. LabVIEW icon view, Blueprint collapsed graphs, and Simulink subsystems are convergence evidence, not a license for new nested graph semantics.", (("NI View As Icon", "https://www.ni.com/docs/en-US/bundle/labview-api-ref/page/properties-and-methods/vi-server/generic/gobject/node/subvi/viewasicon.html"), ("Epic Collapsing Graphs", "https://dev.epicgames.com/documentation/en-us/unreal-engine/collapsing-graphs-in-unreal-engine"), ("MathWorks Subsystem", "https://www.mathworks.com/help/simulink/slref/subsystem.html")), (Current("block-collapse-expanded-2026-09-01.png", "SystemSketch expanded block after reversible view change", "src/blocks/blockVisibility.ts"),)),
    Entry("Manual port visibility and row placement", "have", "A port can already live in a header row, body row, or hidden state. This is the useful analogue of Blueprint As Pin and source-derived subsystem placement because it changes readability without changing Python’s callable interface.", (("Epic Struct Variables", "https://dev.epicgames.com/documentation/en-us/unreal-engine/struct-variables-in-blueprints?application_version=4.27"), ("MathWorks Connect Subsystems", "https://www.mathworks.com/help/simulink/ug/connect-subsystems.html")), (Current("header-port-rows-product-2026-09-01.png", "SystemSketch port rows on a rendered block", "src/blocks/blockModel.ts"),)),
    Entry("Required input, visible default, and wired override", "have", "B01 and B02 were overstated in the earlier report. An empty input already reads as required; a literal/default pill shows the value that will be used; and a connected cable visibly overrides it. A keyword-only badge would add little to that existing contract.", (("NI terminal categories", "https://www.ni.com/docs/en-US/bundle/labview/page/setting-required-recommended-and-optional-inputs-and-outputs.html"), ("Epic Functions", "https://dev.epicgames.com/documentation/en-us/unreal-engine/functions?application_version=4.27")), (Current("literal-pill-product.png", "Unwired literal/default pill", "src/blocks/blockModel.ts"), Current("literal-pill-wired.png", "Connected cable visibly supplying the input", "src/blocks/connections/connectionModel.ts"))),
    Entry("Variadic parameter groups", "have", "Resolved <code>*args</code> and <code>**kwargs</code> already ship as real cableable parameter groups with inspector support. The earlier dictionary's variadic proposal is obsolete; SystemSketch does not need Blueprint's authoring-time Add Pin control.", (("Epic Functions", "https://dev.epicgames.com/documentation/en-us/unreal-engine/functions?application_version=4.27"),), (Current("variadic-port-v5-inspector-live.png", "Shipped variadic parameter ports and inspector", "src/blocks/variadicPorts.ts"),)),
    Entry("Main menu, local files, autosave, and share", "have", "SystemSketch already has the ordinary application commands mature editors need: new/open/open recent/save-copy, local workspace lifecycle, autosave, portable share, and stock undo/redo. A second File/Edit/View menu bar would duplicate this surface.", (("Epic Blueprint Editor Menu", "https://dev.epicgames.com/documentation/unreal-engine/menu-for-the-blueprints-visual-scripting-editor-in-unreal-engine?lang=en-US"), ("MathWorks Simulink Editor", "https://www.mathworks.com/help/simulink/slref/simulinkeditor.html")), (Current("workspace-file-menu.png", "SystemSketch File menu and local-board commands", "src/workspace/LocalWorkspace.tsx"),)),
    Entry("Semantic toolbar and contextual layout actions", "have", "The bottom toolbar already groups stock drawing tools with Block, Branch, Loop, and Pill creation. Selection-scoped menus already expose appearance, port/view controls, Tidy edges, Organize nodes, wrapping, and stock alignment behavior, so a persistent LabVIEW/Simulink formatting ribbon is unnecessary.", (("NI Front Panel Explained", "https://www.ni.com/en/support/documentation/supplemental/08/labview-front-panel-explained.html"), ("MathWorks Simulink Editor", "https://www.mathworks.com/help/simulink/slref/simulinkeditor.html")), (Current("toolbar-family-menu-open.png", "SystemSketch semantic tool family", "src/toolbar/SystemSketchToolbar.tsx"), Current("layout-commands-live-organized-2026-09-02.png", "Selection-scoped layout commands", "src/chrome/SelectionLayoutActions.tsx"))),
    Entry("Command palette and board Find / Replace", "have", "Ctrl+P already searches commands and Ctrl+F already searches and replaces editable text across the board. This covers the useful core of LabVIEW Quick Drop and Simulink action search; the semantic-reference gap is a separate entry below.", (("NI Quick Drop", "https://www.ni.com/en/support/documentation/supplemental/08/boost-labview-productivity-with-quick-drop.html"), ("MathWorks action search", "https://www.mathworks.com/help/simulink/ug/keyword-search-for-actions.html"), ("Epic Blueprint Search", "https://dev.epicgames.com/documentation/en-us/unreal-engine/blueprint-search?application_version=4.27")), (Current("command-palette-commands-2026-09-02.png", "Searchable SystemSketch command palette", "src/commands/SystemSketchCommandPalette.tsx"), Current("command-palette-find-replace-2026-09-02.png", "Board-wide text Find / Replace", "src/commands/boardSearch.ts"))),
    Entry("Searchable shapes and insertion library", "have", "The Shapes library is categorized, searchable, recent-aware, and inserts reusable visual objects; the on-canvas picker supplies semantic Block presets. SystemSketch does not need another LabVIEW Functions, Blueprint Palette, or Simulink block catalog.", (("NI Block Diagram Explained", "https://www.ni.com/en/support/documentation/supplemental/08/labview-block-diagram-explained.html"), ("Epic Blueprint Palette", "https://dev.epicgames.com/documentation/unreal-engine/palette-in-the-bleprints-visual-scripting-editor-for-unreal-engine?lang=en-US"), ("MathWorks Library Browser", "https://www.mathworks.com/help/simulink/slref/librarybrowser.html")), (Current("library-overview-library-2026-09-02.png", "SystemSketch searchable Shapes library", "src/library/ShapeLibraryBrowser.tsx"), Current("unknown-projection-picker-open.png", "Semantic stock Block picker", "src/blocks/connections/blockPicker.ts"))),
    Entry("Selection-following Inspector with Details / Notes", "have", "The right Inspector already follows Blocks, Branches, Loops, connections, ordinary shapes, and batch selections. Block inspection already has Details and Notes tabs; the useful remaining work is source provenance and clearer sibling dock tabs, not a new property system.", (("Epic Details Panel", "https://dev.epicgames.com/documentation/en-us/unreal-engine/details-panel-in-the-blueprints-visual-scriting-editor-for-unreal-engine"), ("MathWorks Property Inspector", "https://www.mathworks.com/help/simulink/slref/propertyinspector.html")), (Current("inspector-field-guidance-2026-09-03.png", "SystemSketch selection-following Inspector", "src/blocks/ui/BlockInspector.tsx"),)),
    Entry("Problems panel with severity, codes, and canvas focus", "have", "The Problems dock already counts and filters errors and warnings, gives each finding a stable code, and focuses the affected board object. Source-span navigation is the narrow missing delta below; a Blueprint Compiler Results or Simulink Diagnostic Viewer clone is not.", (("Epic Compiler Results", "https://dev.epicgames.com/documentation/unreal-engine/compiler-results?application_version=4.27"), ("MathWorks Diagnostic Viewer", "https://www.mathworks.com/help/simulink/slref/diagnosticviewer.html")), (Current("board-diagnostics-problems-2026-09-02.png", "SystemSketch Problems dock", "src/diagnostics/BoardDiagnosticsPanel.tsx"),)),
    Entry("Board Overview, depth navigation, and zoom", "have", "Board Overview lists Frames, Branches, and Expanded Blocks and can focus them; the depth stack jumps to ancestors and steps out; stock zoom/fit/minimap controls cover camera navigation. This already answers the generic Model Browser or LabVIEW Navigation Window need for the current board.", (("Epic Graph Editor", "https://dev.epicgames.com/documentation/en-us/unreal-engine/graph-editor-for-the-blueprints-visual-scripting-editor-in-unreal-engine"), ("MathWorks Simulink Editor", "https://www.mathworks.com/help/simulink/slref/simulinkeditor.html")), (Current("library-overview-panel-2026-09-02.png", "SystemSketch Board Overview and depth chrome", "src/chrome/BoardOverview.tsx"), Current("zoom-controls-shown.png", "Stock zoom and fit controls", "src/SystemSketchUtilities.tsx"))),
    Entry("Anchored comments and source references", "have", "Local comments already anchor to a block, point, region, or page and can retain a source reference. They preserve durable identity beyond a loose visual comment box without inventing a new semantic node.", (("Epic Comments", "https://dev.epicgames.com/documentation/en-us/unreal-engine/comments-in-unreal-engine?lang=en-US"), ("MathWorks Block Comments", "https://www.mathworks.com/help/simulink/ug/collaborate-by-adding-comments-to-blocks.html")), (Current("repo-improvements-local-comments.png", "SystemSketch local canvas comments", "src/comments/commentModel.ts"),)),
    Entry("Preview diff states and intra-value changes", "have", "SystemSketch already marks added, removed, and changed Block/port/cable facts and shows inline before→after value differences under the Preview/Stable review controls. Simulink Model Comparison confirms the navigation pattern; selecting two arbitrary saved versions is a separate workflow decision, not a missing visual vocabulary.", (("MathWorks Model Comparison", "https://www.mathworks.com/help/simulink/ug/understand-model-comparison-results.html"),), (Current("diff-states-marked.png", "SystemSketch Preview diff state and inline value change", "src/blocks/diffState.ts"),)),
    Entry("Async edge styling as presentation vocabulary", "have", "The current async edge treatment is a useful visual distinction but is presentation-only today. Track A identifies the missing analyzer facts needed before the style can truthfully carry semantic meaning.", (("NI Using Wires", "https://www.ni.com/docs/en-US/bundle/labview/page/using-wires-to-link-block-diagram-objects.html"),), (Current("async-edge-style-acceptance.png", "SystemSketch async edge style", "src/blocks/connections/connectionModel.ts"),)),
    Entry("Preset semantic role tags on ordinary ports and wires", "useful", "Activate the existing disabled Tags affordance with a small accepted set: Data by default, then Event, Configuration, State, Control, and Error. These are semantic labels on the same ordinary dataflow; an Error value can use a tunnel bus and an Event can carry type/time/payload/timeout without creating new transports.", (("NI Handling Errors", "https://www.ni.com/docs/en-US/bundle/labview/page/handling-errors.html"), ("Epic Blueprint Communications", "https://dev.epicgames.com/documentation/en-us/unreal-engine/blueprint-communications-in-unreal-engine"), ("MathWorks Signal Types", "https://www.mathworks.com/help/simulink/ug/signal-types.html")), evidence=(Evidence("gap-labview-error-wire-2026-09-03.png", "LabVIEW error-cluster dataflow", "NI · Handling Errors", "https://www.ni.com/docs/en-US/bundle/labview/page/handling-errors.html"), Evidence("gap-blueprint-cast-failure-2026-09-03.png", "Blueprint explicit failure path", "Epic · Blueprint Communications", "https://dev.epicgames.com/documentation/en-us/unreal-engine/blueprint-communications-in-unreal-engine"), Evidence("gap-simulink-function-call-2026-09-03.png", "Simulink dash-dot function-call control signals", "MathWorks · Model Reference Function-Call", "https://www.mathworks.com/help/simulink/slref/model-reference-function-call.html")), proposal=PROPOSALS["semantic_tags"], lift="<b>Lift · small to medium.</b> The inspector section already exists but is disabled. Add stable tag data, redundant accessible cues, and conservative analyzer defaults without changing routing or execution semantics."),
    Entry("Contextual source / provenance lens", "useful", "LabVIEW Context Help, Blueprint Details, and Simulink Property Inspector all keep explanation close to the current selection. Extend the existing Inspector with a read-only Source section: projection kind, declaration/span, canonical definition, occurrences, docstring, and the meaning of any semantic role tag.", (("NI Context Help guidance", "https://www.ni.com/en/support/documentation/supplemental/21/driver-and-vi-library-development-guidelines.html"), ("Epic Details Panel", "https://dev.epicgames.com/documentation/en-us/unreal-engine/details-panel-in-the-blueprints-visual-scriting-editor-for-unreal-engine"), ("MathWorks Property Inspector", "https://www.mathworks.com/help/simulink/slref/propertyinspector.html")), evidence=(LV_CONTEXT_HELP, BP_DETAILS, SL_INSPECTOR), proposal=PROPOSALS["source_help"], lift="<b>Lift · medium.</b> It needs trustworthy analyzer provenance and source-navigation plumbing; the panel itself reuses current Inspector chrome and remains read-only."),
    Entry("Source project, definition, and occurrence navigator", "useful", "Project Explorer, My Blueprint, and Model Browser converge on a searchable hierarchy outside the canvas. SystemSketch's Board Overview already handles board structure; the missing sibling is a Python-owned tree from files/modules to definitions, callers/occurrences, and their existing projections.", (("NI Project Explorer guidance", "https://www.ni.com/en/support/documentation/supplemental/08/best-practices-for-managing-ni-labview-applications-using-the-pr.html"), ("Epic My Blueprint Panel", "https://dev.epicgames.com/documentation/unreal-engine/my-blueprint-panel-in-the-blueprints-visual-scripting-editor-for-unreal-engine?lang=en-US"), ("MathWorks Simulink Editor", "https://www.mathworks.com/help/simulink/slref/simulinkeditor.html")), evidence=(LV_PROJECT, BP_OUTLINE, SL_BROWSER), proposal=PROPOSALS["source_explorer"], lift="<b>Lift · medium to high.</b> Requires a stable source/project symbol index and occurrence identity. It must not mutate files, create definitions, manage deploy targets, or become a parallel project model."),
    Entry("Semantic symbol and Find References search", "useful", "The shipped Ctrl+F finds editable board text; this adds identity-aware results for definitions, linked occurrences, ports, types, defaults, and references. Blueprint's MemberGuid-based references show the key constraint: same spelling is not enough. Results should select/fit a board occurrence or reveal its source span.", (("NI Quick Drop", "https://www.ni.com/en/support/documentation/supplemental/08/boost-labview-productivity-with-quick-drop.html"), ("Epic Find Result Panel", "https://dev.epicgames.com/documentation/unreal-engine/find-result-panel?application_version=4.27"), ("MathWorks Finder", "https://www.mathworks.com/help/simulink/slref/finder.html")), evidence=(LV_QUICK_DROP, BP_FIND, SL_FINDER), proposal=PROPOSALS["semantic_search"], lift="<b>Lift · medium to high.</b> The result UI can reuse Ctrl+P, but a reliable semantic/projection index and scope model—current depth, board, then workspace—are prerequisite."),
    Entry("Source-linked Problems actions", "useful", "SystemSketch already models optional source path, symbol, and line spans in diagnostics but does not surface them. When a real analyzer supplies those fields, each finding should offer both current canvas focus and source navigation, while retaining code, severity, and explanation.", (("NI Debugging Techniques", "https://www.ni.com/en/support/documentation/supplemental/12/debugging-techniques-in-labview.html"), ("Epic Compiler Results", "https://dev.epicgames.com/documentation/unreal-engine/compiler-results?application_version=4.27"), ("MathWorks Diagnostic Viewer", "https://www.mathworks.com/help/simulink/slref/diagnosticviewer.html")), evidence=(LV_ERROR_LIST, BP_RESULTS, SL_DIAGNOSTICS), proposal=PROPOSALS["diagnostic_source"], lift="<b>Lift · small to medium.</b> The data model already reserves the fields. Add guarded rendering, source-open behavior, and tests that absent or stale spans never produce a false link."),
    Entry("Stable right-dock tabs", "useful", "SystemSketch already owns Inspector, Problems, Comments, and Board Overview surfaces, but they replace one another behind separate commands. Blueprint and Simulink make sibling panes and tabs visible. A compact tab row would preserve context and expose the current surface without importing arbitrary IDE docking.", (("Epic Graph Editor", "https://dev.epicgames.com/documentation/en-us/unreal-engine/graph-editor-for-the-blueprints-visual-scripting-editor-in-unreal-engine"), ("MathWorks Property Inspector", "https://www.mathworks.com/help/simulink/slref/propertyinspector.html")), evidence=(BP_GRAPH_EDITOR, SL_INSPECTOR), proposal=PROPOSALS["dock_tabs"], lift="<b>Lift · medium.</b> Consolidate existing surfaces behind one stable tab model, preserve selection-following Inspector behavior, responsive collapse, keyboard order, and current dismiss semantics."),
    Entry("Named local review landmarks / saved views", "useful", "Blueprint bookmarks and Simulink viewmarks independently preserve graph/hierarchy location, camera position, and zoom. Add named personal review points near Board Overview so a large board can be revisited without abusing comments or duplicating boards.", (("Epic Blueprint Bookmarks", "https://dev.epicgames.com/documentation/en-us/unreal-engine/working-with-bookmarks-for-blueprint-graphs-in-unreal-engine"), ("MathWorks Bookmark Your Place", "https://www.mathworks.com/help/simulink/ug/bookmark-your-place-in-models.html")), evidence=(BP_BOOKMARKS, SL_VIEWMARKS), proposal=PROPOSALS["landmarks"], lift="<b>Lift · low to medium.</b> Persist board identity, depth scope, camera, and optional target shape locally. Define stale-target fallback and keep personal landmarks out of shared semantic source truth."),
    Entry("Back / Forward navigation history and scope breadcrumb", "useful", "Depth Stack already jumps to ancestors. Blueprint and Simulink additionally remember navigation jumps and show the current nested path. Add session-local Back/Forward around reference search, outline, source, landmark, and depth jumps; keep the breadcrumb tied to real source and canvas scope rather than permanent arbitrary graph tabs.", (("Epic Graph Editor", "https://dev.epicgames.com/documentation/en-us/unreal-engine/graph-editor-for-the-blueprints-visual-scripting-editor-in-unreal-engine"), ("MathWorks Simulink Editor", "https://www.mathworks.com/help/simulink/slref/simulinkeditor.html")), evidence=(BP_GRAPH_EDITOR, SL_EDITOR), proposal=PROPOSALS["document_tabs"], lift="<b>Lift · small to medium.</b> Centralize focus/fit/depth jumps, record bounded personal history, and restore selection/camera safely when targets disappear."),
    Entry("Focused component-interface lens", "useful", "A reader sometimes needs only a component's public boundary. Simulink's Component Interface View is strong precedent: show the selected component's canonical inputs/outputs and trace where a chosen port is used, while leaving the source-derived Block itself untouched.", (("MathWorks Component Interface View", "https://www.mathworks.com/help/simulink/slref/componentinterfaceview.html"), ("NI Icon and Connector Panes", "https://www.ni.com/en/support/downloads/instrument-drivers/tools-resources/instrument-driver-guidelines/icon-and-connector-panes.html"), ("Epic Functions", "https://dev.epicgames.com/documentation/en-us/unreal-engine/functions?application_version=4.27")), evidence=(Evidence("gap-labview-connector-contract-2026-09-03.png", "LabVIEW aligned connector-pane boundary", "NI · Icon and Connector Panes", "https://www.ni.com/en/support/downloads/instrument-drivers/tools-resources/instrument-driver-guidelines/icon-and-connector-panes.html"), Evidence("gap-blueprint-function-call-2026-09-03.png", "Blueprint generated function interface", "Epic · Functions", "https://dev.epicgames.com/documentation/en-us/unreal-engine/functions?application_version=4.27"), SL_INTERFACE), proposal=PROPOSALS["component_interface"], lift="<b>Lift · medium to high.</b> Resolve one canonical component definition and its occurrences, then provide a read-only port list and trace. No independent schema or canvas-created interface is allowed."),
    Entry("Structured cable hierarchy and static source/destination trace", "useful", "Simulink's Signal Hierarchy Viewer follows a selected compound signal, exposes its field tree, and traces a member to sources and destinations. Extend SystemSketch's existing Connection Inspector with analyzer-known record fields and endpoint navigation—static graph facts, not compiled dimensions or runtime values.", (("MathWorks Signal Hierarchy Viewer", "https://www.mathworks.com/help/simulink/slref/signalhierarchyviewer.html"),), evidence=(SL_SIGNAL_HIERARCHY,), proposal=PROPOSALS["signal_trace"], lift="<b>Lift · medium.</b> Reuse connection identity and Split field facts, add a stable nested-type view, and define honest unknown states for dynamic mappings and unresolved frameworks."),
    Entry("Board-wide semantic data table", "useful", "The Inspector is selection-scoped; a large board can also benefit from one filterable table of canonical Blocks, ports, connections, types, defaults, and semantic roles. Simulink's Model Data Editor supplies the outside-canvas precedent, but the SystemSketch version stays read-only and source-linked rather than becoming a MATLAB workspace or schema editor.", (("MathWorks Model Data Editor", "https://www.mathworks.com/help/simulink/slref/modeldataeditor.html"),), evidence=(SL_DATA_EDITOR,), proposal=PROPOSALS["data_table"], lift="<b>Lift · medium.</b> Build a virtualized board index over existing canonical identities, share filters with semantic search, and make every row focus the canvas or source. No cell edit may create a competing source of truth."),
    Entry("Run / Pause / Stop strip for an explicit runtime adapter", "useful", "The requested play-button precedent is real: LabVIEW, Blueprint, and Simulink all name a run target, expose state-dependent Run/Pause/Stop controls, and report status outside the canvas. In SystemSketch this is useful only when an explicit Python/test/ROS adapter exists; drawing alone must never execute code.", (("NI Block Diagram Explained", "https://www.ni.com/en/support/documentation/supplemental/08/labview-block-diagram-explained.html"), ("Epic Blueprint Toolbar", "https://dev.epicgames.com/documentation/en-us/unreal-engine/toolbar-in-the-blueprints-visual-scripting-editor-for-unreal-engine"), ("MathWorks Simulink Editor", "https://www.mathworks.com/help/simulink/slref/simulinkeditor.html")), evidence=(LV_TOOLBAR, BP_TOOLBAR, SL_EDITOR), proposal=PROPOSALS["run_controls"], lift="<b>Lift · very high and conditional.</b> First define sandboxing, target discovery, process lifecycle, cancellation, stdout/errors, and board/source revision identity. Do not ship inert play chrome before that contract exists."),
    Entry("Recorded-trace playback and execution highlighting", "useful", "Step and highlight controls become defensible without turning the board into a simulator when they replay an explicit recorded trace. The active Block/cable is a temporary lens with a known trace position, and Back/Forward/Play operate evidence rather than edit source.", (("NI Debugging Techniques", "https://www.ni.com/en/support/documentation/supplemental/12/debugging-techniques-in-labview.html"), ("Epic Blueprint Debugger", "https://dev.epicgames.com/documentation/en-us/unreal-engine/blueprint-debugger-in-unreal-engine"), ("MathWorks Breakpoints List", "https://www.mathworks.com/help/simulink/slref/breakpointslist.html")), evidence=(LV_DEBUG, BP_DEBUG, SL_BREAKPOINTS), proposal=PROPOSALS["trace_controls"], lift="<b>Lift · high.</b> Specify a trace event schema, source-revision match, occurrence mapping, temporal controls, and nonpersistent highlight layer. Live stepping remains a later runtime-adapter concern."),
    Entry("Read-only live or recorded value probes", "useful", "LabVIEW Probe Watch, Blueprint watched pins, and Simulink's Data Inspector all expose values produced during a run. A SystemSketch probe may decorate an existing port/cable only when an explicit run or imported trace supplies the value; it is never an editable literal or canonical board state.", (("NI Debugging Techniques", "https://www.ni.com/en/support/documentation/supplemental/12/debugging-techniques-in-labview.html"), ("Epic Blueprint Debugger", "https://dev.epicgames.com/documentation/en-us/unreal-engine/blueprint-debugger-in-unreal-engine"), ("MathWorks Create a Simple Model", "https://www.mathworks.com/help/simulink/gs/create-a-simple-model.html")), evidence=(LV_PROBE, BP_WATCH, SL_DATA_INSPECTOR), proposal=PROPOSALS["live_values"], lift="<b>Lift · high after trace/run work.</b> It needs value capture, safe serialization/redaction, source-revision mapping, history limits, and a strict visual distinction from authorable literals and defaults."),
    Entry("Standalone keyword-only or recommended-terminal badges", "skip", "Empty versus defaulted/wired inputs are already readable, and Zach is not interested in keyword-only as a standalone UI tier. Python has no LabVIEW recommended-wiring legality; keep the source spelling available in the Inspector instead of adding badges.", (("NI Terminal Categories", "https://www.ni.com/docs/en-US/bundle/labview/page/setting-required-recommended-and-optional-inputs-and-outputs.html"), ("Epic Functions", "https://dev.epicgames.com/documentation/en-us/unreal-engine/functions?application_version=4.27"))),
    Entry("Authorable masks, callbacks, class defaults, or GUI type/schema editors", "skip", "Simulink masks and Type Editor, Blueprint Class Defaults, and LabVIEW VI property systems are parallel programming/configuration authorities. Python source remains canonical; SystemSketch may explain those facts but must not author them in a second UI.", (("MathWorks Dynamic Mask Dialog", "https://www.mathworks.com/help/simulink/ug/create-dynamic-mask-dialog-boxes.html"), ("MathWorks Type Editor", "https://www.mathworks.com/help/simulink/slref/typeeditor.html"), ("Epic Blueprint Defaults", "https://dev.epicgames.com/documentation/unreal-engine/blueprint-editor-defaults-tab"), ("NI VI Properties", "https://www.ni.com/docs/en-US/bundle/labview-api-ref/page/dialog-boxes/execution-page-vi-properties-dialog-box.html"))),
    Entry("Wire-driven hiding or canvas-created signature ports", "skip", "Blueprint can hide unconnected pins and Simulink can add/reposition subsystem ports because their graphs own the program. Current wiring must not redefine a Python signature, field schema, or default.", (("Epic Struct Variables", "https://dev.epicgames.com/documentation/en-us/unreal-engine/struct-variables-in-blueprints?application_version=4.27"), ("MathWorks Connect Subsystems", "https://www.mathworks.com/help/simulink/ug/connect-subsystems.html"))),
    Entry("Second node/function palette", "skip", "LabVIEW Functions, Blueprint Palette, and Simulink Library Browser are authoring catalogs. SystemSketch already has a Shapes library and semantic stock Block picker; Python calls/operators stay source-derived rather than draggable library nodes.", (("NI Block Diagram Explained", "https://www.ni.com/en/support/documentation/supplemental/08/labview-block-diagram-explained.html"), ("Epic Blueprint Palette", "https://dev.epicgames.com/documentation/unreal-engine/palette-in-the-bleprints-visual-scripting-editor-for-unreal-engine?lang=en-US"), ("MathWorks Library Browser", "https://www.mathworks.com/help/simulink/slref/librarybrowser.html"))),
    Entry("Mutable project, asset, deployment, and source-control manager", "skip", "LabVIEW targets/build specifications, Unreal Content Browser/source control, and Simulink project/dependency controls belong to their host ecosystems. The useful source navigator above is intentionally read-only.", (("NI Project Explorer Guidance", "https://www.ni.com/en/support/documentation/supplemental/08/best-practices-for-managing-ni-labview-applications-using-the-pr.html"), ("Epic Blueprint Editor Menu", "https://dev.epicgames.com/documentation/unreal-engine/menu-for-the-blueprints-visual-scripting-editor-in-unreal-engine?lang=en-US"), ("MathWorks Referenced Files Pane", "https://www.mathworks.com/help/simulink/slref/referencedfilespane.html"))),
    Entry("Large workflow ribbon, arbitrary docking, and layout reset system", "skip", "Simulink's Simulation/Debug/Modeling/Format/Apps toolstrip and Unreal's freely dockable editor shell serve broad host suites. SystemSketch should expose compact contextual commands and a stable dock, not recreate an IDE shell.", (("MathWorks Simulink Editor", "https://www.mathworks.com/help/simulink/slref/simulinkeditor.html"), ("Epic Blueprint Class UI", "https://dev.epicgames.com/documentation/unreal-engine/blueprints-visual-scripting-user-interface-for-blueprint-classes-in-unreal-engine"))),
    Entry("Solver, pacing, simulation modes, hardware targets, and deployment", "skip", "These controls configure numerical simulators or target hardware. Even if a basic explicit Run adapter is later approved, SystemSketch should not imply Simulink solver semantics, LabVIEW hardware execution, or Unreal PIE modes for ordinary Python.", (("MathWorks Simulation Execution", "https://www.mathworks.com/help/simulink/ug/controlling-execution-of-a-simulation.html"), ("NI Block Diagram Explained", "https://www.ni.com/en/support/documentation/supplemental/08/labview-block-diagram-explained.html"), ("Epic Blueprint Toolbar", "https://dev.epicgames.com/documentation/en-us/unreal-engine/toolbar-in-the-blueprints-visual-scripting-editor-for-unreal-engine"))),
    Entry("Compile / Update Diagram button without a real compiler contract", "skip", "Blueprint Compile, LabVIEW Broken Run, and Simulink Update Diagram report tool-owned compilation states. The existing Problems panel should stay analyzer-driven; an inert Compile button would claim authority SystemSketch does not have.", (("Epic Blueprint Toolbar", "https://dev.epicgames.com/documentation/en-us/unreal-engine/toolbar-in-the-blueprints-visual-scripting-editor-for-unreal-engine"), ("NI Block Diagram Explained", "https://www.ni.com/en/support/documentation/supplemental/08/labview-block-diagram-explained.html"), ("MathWorks Simulink Editor", "https://www.mathworks.com/help/simulink/slref/simulinkeditor.html"))),
    Entry("Full live-instance debugger, breakpoint manager, and debug-object picker", "skip", "The recorded-trace lens above is deliberately narrower. Per-instance call stacks, breakpoint mutation, possess/eject, execution scheduler control, and debug-target discovery require an execution host and should not be imitated as decorative chrome.", (("NI Debugging Techniques", "https://www.ni.com/en/support/documentation/supplemental/12/debugging-techniques-in-labview.html"), ("Epic Blueprint Debugger", "https://dev.epicgames.com/documentation/en-us/unreal-engine/blueprint-debugger-in-unreal-engine"), ("MathWorks Breakpoints List", "https://www.mathworks.com/help/simulink/slref/breakpointslist.html"))),
    Entry("Unreal Components, Viewport, Construction Script, and Class modes", "skip", "These panels author Actor composition, 3D transforms, and lifecycle scripts. They do not reveal generic Python/dataflow facts; Board Overview and Inspector already carry the transferable hierarchy/selection patterns.", (("Epic Blueprint Class UI", "https://dev.epicgames.com/documentation/unreal-engine/blueprints-visual-scripting-user-interface-for-blueprint-classes-in-unreal-engine"),)),
    Entry("Full time-series analysis and signal-logging workbench", "skip", "Simulink Data Inspector plots, compares, aligns, and exports simulator runs. A small read-only port/cable probe may be useful, but a numerical analysis suite is a separate product surface.", (("MathWorks Simulation Data Inspector", "https://www.mathworks.com/help/simulink/slref/simulationdatainspector.html"),)),
    Entry("Diagnostic suppression, auto-fix, runtime-stage comparison, and global logs", "skip", "The focused Problems dock is the correct boundary. Toolchain fix buttons, suppression policies, baseline comparison, compile logs, and runtime message consoles require authorities outside the board.", (("NI Debugging Techniques", "https://www.ni.com/en/support/documentation/supplemental/12/debugging-techniques-in-labview.html"), ("Epic Compiler Results", "https://dev.epicgames.com/documentation/unreal-engine/compiler-results?application_version=4.27"), ("MathWorks Diagnostic Viewer", "https://www.mathworks.com/help/simulink/slref/diagnosticviewer.html"))),
    Entry("Permanent arbitrary graph tabs", "skip", "Blueprint and Simulink tabs reflect graph documents owned by those editors. Session-local Back/Forward plus source/depth breadcrumbs solve the navigation problem without introducing a second document model inside a board.", (("Epic Graph Editor", "https://dev.epicgames.com/documentation/en-us/unreal-engine/graph-editor-for-the-blueprints-visual-scripting-editor-in-unreal-engine"), ("MathWorks Simulink Editor", "https://www.mathworks.com/help/simulink/slref/simulinkeditor.html"))),
)


