def status(value: str) -> str:
    labels = {"have": "Already have", "useful": "Missing, would be useful", "skip": "Missing, would not be useful"}
    return f'<span class="status {value}">{labels[value]}</span>'


def source_links(entry: Entry) -> str:
    if not entry.links:
        return ""
    return '<p class="source-links"><b>Primary documentation:</b> ' + " · ".join(link(name, url) for name, url in entry.links) + "</p>"


def row(entry: Entry, prefix: str, number: int) -> str:
    if entry.status == "skip":
        return f'<tr class="skip-row" id="{prefix}-{number}"><td colspan="2">{status(entry.status)}<h3>{esc(entry.term)}</h3><p>{entry.description}</p>{source_links(entry)}</td></tr>'
    if entry.status == "useful":
        assert entry.evidence and entry.proposal and entry.lift, entry.term
    visual = ""
    if entry.current:
        visual += '<div class="screen-heading">Existing SystemSketch UI</div><div class="evidence-grid">' + "".join(current_figure(x) for x in entry.current) + "</div>"
    if entry.evidence:
        heading = "Official reference UI" if not entry.current else "Official cross-tool reference UI"
        visual += f'<div class="screen-heading">{heading}</div><div class="evidence-grid">' + "".join(source_figure(x) for x in entry.evidence) + "</div>"
    if entry.proposal:
        visual += entry.proposal + f'<p class="lift">{entry.lift}</p>'
    return f'<tr id="{prefix}-{number}"><td class="meaning">{status(entry.status)}<div class="kicker">{prefix.upper()} · {number:02d}</div><h3>{esc(entry.term)}</h3><p>{entry.description}</p>{source_links(entry)}</td><td class="visual">{visual}</td></tr>'


def bucket(entries: tuple[Entry, ...], kind: str, prefix: str) -> str:
    selected = [entry for entry in entries if entry.status == kind]
    headings = {
        "have": ("Already have", "Current SystemSketch UI is the proof; no hypothetical replacement drawing."),
        "useful": ("Missing, would be useful", "Every row: description → official screenshots → original SystemSketch sketch → honest lift."),
        "skip": ("Missing, would not be useful", "Text only by design: these would add palette or host-runtime semantics, not reveal Python."),
    }
    heading, note = headings[kind]
    # IDs stay unique across the three buckets so external review links and
    # screenshot clips cannot accidentally land on an earlier row with the same
    # ordinal.
    rows = "".join(row(entry, f"{prefix}-{kind}", i) for i, entry in enumerate(selected, 1))
    return f'<div class="bucket"><div class="bucket-head"><h3>{heading}</h3><p>{note}</p></div><table class="dictionary"><thead><tr><th>Concept and reading</th><th>Evidence and SystemSketch projection</th></tr></thead><tbody>{rows}</tbody></table></div>'


def track(anchor: str, label: str, description: str, entries: tuple[Entry, ...]) -> str:
    return f'<section id="{anchor}"><div class="section-head"><div><div class="tag {label}">{label.upper()} · dictionary</div><h2>Track {label.upper()} · {"node and block vocabulary" if label == "a" else "UI controls and application chrome"}</h2></div><p>{description}</p></div>{bucket(entries, "have", label)}{bucket(entries, "useful", label)}{bucket(entries, "skip", label)}</section>'


def revised_body(
    branch: str,
    base: str,
    counts: dict[str, int],
    capture_count: int,
    source_index: str,
) -> str:
    """Current report shell; dictionary rows above remain the canonical data."""
    return f'''
<header>
  <div class="eyebrow">SystemSketch · deep research dictionary · 04 September 2026</div>
  <h1>LabVIEW, Unreal Blueprint &amp; Simulink<br>Vocabulary and UI Controls Gap Analysis</h1>
  <p class="lede">A concept-by-concept evidence dictionary, now including the application chrome outside the canvas: menus, toolbars, run controls, inspectors, tabs, navigators, search, diagnostics, bookmarks, and debugging surfaces.</p>
  <div class="scope">
    <div class="card"><h2>How to read a useful row</h2><p>Every useful entry follows the requested order: plain-language description, real official-documentation screenshots side by side, then an original SystemSketch proposal and honest implementation lift.</p></div>
    <div class="card"><h2>The source-authority filter</h2><p>Borrow controls that reveal a Python, board, run, or trace fact. Reject controls that would make the canvas a second program, schema, simulator, asset database, or deployment system.</p></div>
  </div>
</header>
<nav><div class="shell"><a href="#framing">Framing</a><a href="#track-a">Track A · vocabulary</a><a href="#track-b">Track B · controls</a><a href="#thinking">Sharpened</a><a href="#decision">Decision surface</a><a href="#sources">Sources</a></div></nav>
<main class="shell">
  <section id="framing">
    <div class="section-head"><div><div class="tag a">Corrected conclusion</div><h2>More already exists; the remaining gaps are specific</h2></div><p>Split, required/default/override readability, variadic groups, the Inspector, Problems, command search, library, Board Overview, depth navigation, comments, and layout commands are already real SystemSketch UI—not proposals.</p></div>
    <div class="filter"><b>What changed after Zach's review:</b> <b>Split</b> moved to Already have. <b>Set attributes</b> and <b>Select</b> are approved stock-block directions. Error, event, state, and configuration remain ordinary data with optional semantic tags. Async remains a direct <b>dashed</b> data edge. Clock/Trigger is a visible source. Derived statecharts are out, and behavior-tree work is deferred to its own later research. Track B now inventories the full off-canvas editor surface rather than only per-Block controls.</div>
    <div class="stats"><div class="stat"><b>{counts['have']} shipped</b><span>Current-SystemSketch screenshot evidence.</span></div><div class="stat"><b>{counts['useful']} useful gaps</b><span>Official screenshots + original proposals.</span></div><div class="stat"><b>{counts['skip']} exclusions</b><span>Compact, text-only non-gaps.</span></div><div class="stat"><b>{capture_count} captures</b><span>Unique official screenshots used by the dictionary.</span></div></div>
  </section>
  {track('track-a', 'a', 'Concepts pyblocks might render as a Block, region, port, source, or cable when the source really carries that shape. Entries are organized by concept, not vendor.', TRACK_A)}
  {track('track-b', 'b', 'Everything around the canvas: menus, toolbar commands, inspectors and their tabs, navigation, search, diagnostics, run/trace controls, and other panels. Existing SystemSketch seams are audited before anything is called missing.', TRACK_B)}
  <section id="thinking">
    <div class="section-head"><div><div class="tag b">Synthesis</div><h2>Your thinking, sharpened</h2></div><p>These are scoped inferences from primary documentation and the live tree—not claims that the three reference tools share one execution model.</p></div>
    <div class="thinking">
      <article class="card"><h3>1 · Split was already the answer.</h3><p>The stock Split preset and its named accessor rows already implement the useful Unbundle By Name / Split Struct / Bus Selector reading.</p></article>
      <article class="card"><h3>2 · Set attributes is the missing twin.</h3><p>The designed batched named update should ship as a stock Block with ordinary record data in/out; mutation metadata remains separate.</p></article>
      <article class="card"><h3>3 · Select is data, not execution.</h3><p>Two candidate values plus one Boolean control value map cleanly to Python's conditional expression and one ordinary output.</p></article>
      <article class="card"><h3>4 · Event and error are roles, not transports.</h3><p>Data/Event/Configuration/State/Control/Error tags explain ordinary ports and arrows. No dispatcher cable, exception rail, or top-edge side effect is needed.</p></article>
      <article class="card"><h3>5 · The Simulink E-lines are control events.</h3><p>E1/E2 schedule periodic function calls and E3 is interrupt-driven; their dash-dot style supports a redundant semantic cue, not a generic async-queue claim.</p></article>
      <article class="card"><h3>6 · Clock/Trigger must be explicit.</h3><p>A visible source can emit ticks as typed data. It must name its rate/adapter and never hide a scheduler in the drawing.</p></article>
      <article class="card"><h3>7 · Off-canvas convergence is mostly already present.</h3><p>SystemSketch already has the menu, command search, library, Inspector, Problems, overview, depth, comments, zoom, and contextual layout core.</p></article>
      <article class="card"><h3>8 · The best chrome gaps are semantic.</h3><p>Source provenance, definition/reference navigation, source-linked diagnostics, landmarks, cable hierarchy, interface tracing, and a board-wide fact table reveal identity the current generic panes cannot.</p></article>
      <article class="card"><h3>9 · Play controls need a real authority.</h3><p>Run/Pause/Stop is worth designing only around an explicit target adapter; trace playback and probes must be transient evidence, never board state.</p></article>
    </div>
  </section>
  <section id="decision">
    <div class="section-head"><div><div class="tag a">Decision surface</div><h2>Done / left / needs Zach / deliberately not done</h2></div><p>This remains research: it records approved directions and decision surfaces but makes no hidden product, schema, analyzer, or runtime change.</p></div>
    <div class="decision">
      <article class="card"><h3>Done</h3><ul><li>Reclassified Split, defaults/overrides, and variadics from missing to shipped.</li><li>Ran independent LabVIEW, Blueprint, and Simulink application-chrome passes.</li><li>Added every current major menu/panel seam and the useful semantic gaps.</li><li>Embedded {capture_count} unique official-reference screenshots.</li></ul></article>
      <article class="card"><h3>Left</h3><ul><li>Ship approved Set attributes and Select stock Blocks.</li><li>Design Clock/Trigger source facts and enable semantic tag presets.</li><li>Prototype Source lens, source-linked Problems, semantic search, landmarks, and the board-wide fact table.</li><li>Define a runtime/trace adapter contract before any play controls.</li></ul></article>
      <article class="card"><h3>Needs Zach</h3><ul><li>Should the right surfaces become explicit tabs?</li><li>Should source/project navigation begin at one board or the whole workspace?</li><li>Do Run controls belong now, or should imported trace playback come first?</li><li>Should semantic tags be analyzer-only, user-chosen presentation, or both with provenance?</li></ul></article>
      <article class="card"><h3>Deliberately not done</h3><ul><li>No bespoke event/error transport or derived statechart.</li><li>No vendor node palette, ribbon, schema editor, mask system, or mutable project manager.</li><li>No inert Compile/Play buttons, solver UI, deployment settings, or fake live debugger.</li><li>Behavior trees remain a separate later research track.</li></ul></article>
    </div>
  </section>
  <section id="sources"><div class="section-head"><div><div class="tag b">Primary only</div><h2>Numbered source index</h2></div><p>Every reference screenshot caption links directly to its NI, Epic, or MathWorks documentation page. The capture is embedded so the evidence remains visible with this revision.</p></div><ol class="sources">{source_index}</ol></section>
  <footer>Canonical source: <code>{esc(SOURCE_NOTE.relative_to(REPO))}</code> · generated by <code>docs/build_labview_blueprint_simulink_gap_analysis.py</code> · branch <code>{esc(branch)}</code>, source base <code>{esc(base)}</code>. The durable review URL pins the exact revision. Official screenshots are embedded evidence; blue proposal diagrams are original SystemSketch sketches.</footer>
</main>
'''


def indexed_sources() -> tuple[tuple[str, str, str], ...]:
    """Return one numbered index that cannot drift behind dictionary citations."""
    indexed: list[tuple[str, str, str]] = []
    seen_urls: set[str] = set()

    def add(name: str, note: str, url: str) -> None:
        if url in seen_urls:
            return
        seen_urls.add(url)
        indexed.append((name, note, url))

    for name, note, url in SOURCES:
        add(name, note, url)
    for entry in TRACK_A + TRACK_B:
        for name, url in entry.links:
            add(name, f"Primary documentation cited by the {entry.term} dictionary entry.", url)
        for item in entry.evidence:
            add(item.source, f"Official screenshot evidence for {entry.term}.", item.url)
    return tuple(indexed)


def build() -> str:
    branch = git("branch", "--show-current") or "detached"
    head = git("rev-parse", "--short", "HEAD")
    base = git("merge-base", "HEAD", "main")[:7] or head
    counts = {kind: sum(e.status == kind for e in TRACK_A + TRACK_B) for kind in ("have", "useful", "skip")}
    capture_count = len({
        item.image
        for entry in TRACK_A + TRACK_B
        for item in entry.evidence
    })
    source_index = "".join(f'<li class="source"><b>{esc(name)}</b><br>{esc(note)}<br>{link(name, url)}</li>' for name, note, url in indexed_sources())
    body = f'''<header><div class="eyebrow">SystemSketch · deep research dictionary · 04 September 2026</div><h1>LabVIEW, Unreal Blueprint &amp; Simulink<br>Vocabulary and UI Controls Gap Analysis</h1><p class="lede">A table-like evidence dictionary: mature visual-programming tools as reading-grammar precedent, never as a template for a second Python authoring language.</p><div class="scope"><div class="card"><h2>How to read a useful row</h2><p>Useful entries are deliberately in this order: plain-language description, actual vendor documentation screenshots side by side, then an original SystemSketch proposal drawing. The drawing is a translation hypothesis, not a vendor icon redraw.</p></div><div class="card"><h2>The filter</h2><p>A proposal earns space only if pyblocks could recognise a real Python semantic fact and the visual makes that fact clearer without giving the canvas a second program to maintain.</p></div></div></header><nav><div class="shell"><a href="#framing">Framing</a><a href="#track-a">Track A · vocabulary</a><a href="#track-b">Track B · controls</a><a href="#thinking">Sharpened</a><a href="#decision">Decision surface</a><a href="#sources">Sources</a></div></nav><main class="shell"><section id="framing"><div class="section-head"><div><div class="tag a">Conclusion</div><h2>Borrow constraints, not palettes</h2></div><p>The positive gaps are intentionally narrow: named partial updates, value selection, explicit outcomes, queue/event relations, a high-bar mode region, and source-derived interface exposure. The rest of the reference surface mostly belongs to authoring tools or host runtimes.</p></div><div class="filter"><b>Why convergence matters:</b> independent tools keep converging on visible joins, prior values, named fields, and explicit outcomes because dataflow puts hard constraints on an honest drawing. That is evidence for a source-derived presentation grammar—not permission to reproduce a LabVIEW, Blueprint, or Simulink library.</div><div class="stats"><div class="stat"><b>{counts['have']} shipped</b><span>Real current-SystemSketch UI evidence.</span></div><div class="stat"><b>{counts['useful']} candidates</b><span>Full evidence + original proposal sketches.</span></div><div class="stat"><b>{counts['skip']} exclusions</b><span>Compact text-only non-gaps.</span></div><div class="stat"><b>23 captures</b><span>Primary official-doc screenshots embedded.</span></div></div></section>{track('track-a', 'a', 'Concepts pyblocks might render as a block, region, port, or relation when source really carries the shape. Entries are organized by concept, not vendor.', TRACK_A)}{track('track-b', 'b', 'Controls that change how an existing source-derived block reads. The question is always whether a control reveals a Python fact or imports an authoring/runtime surface.', TRACK_B)}<section id="thinking"><div class="section-head"><div><div class="tag b">Synthesis</div><h2>Your thinking, sharpened</h2></div><p>These are deliberately scoped inferences from the cited documentation and the current tree—not claims that the tools share an execution model.</p></div><div class="thinking"><article class="card"><h3>1 · The error wire’s lesson is visible outcome, not plumbing.</h3><p>Python’s honest translation is a source-aware exception/narrowing boundary, never a red pin placed on every ordinary call.</p></article><article class="card"><h3>2 · Async needs identity, not only a dash pattern.</h3><p>The existing style becomes semantic only when the analyzer can name a queue, await, registration, or callback contract.</p></article><article class="card"><h3>3 · Named fields converge because identity matters.</h3><p>Unbundle By Name, struct pins, and bus selection preserve named-member identity rather than positional coincidence.</p></article><article class="card"><h3>4 · Python has a cleaner interface vocabulary.</h3><p>Required/defaulted/keyword-only/variadic is more truthful than LabVIEW’s recommended wiring tier and does not make a cable legal or illegal.</p></article><article class="card"><h3>5 · State is a semantic commitment.</h3><p>Stateflow is compelling because the chart owns a true state model. An inferred statechart for ordinary enum-and-if code would mislead.</p></article><article class="card"><h3>6 · Parameter dialogs divide at authority.</h3><p>A generated source lens could help a reader; an authorable mask or callback system would create another program on the canvas.</p></article></div></section><section id="decision"><div class="section-head"><div><div class="tag a">Next decision</div><h2>Decision surface</h2></div><p>No product code changes are hidden in this research artifact. Useful entries are staged options, not implementation commitments.</p></div><div class="decision"><article class="card"><h3>Done</h3><ul><li>Rebuilt the report as two extensive concept dictionaries.</li><li>Captured and embedded 23 primary-source reference images.</li><li>Used actual SystemSketch UI captures for every shipped entry.</li></ul></article><article class="card"><h3>Left</h3><ul><li>Choose one exception/narrowing shape and one async/event idiom before analyzer work.</li><li>Define safe record-field discovery and a small portless-effect experiment.</li><li>Prototype signature density only after analyzer facts exist.</li></ul></article><article class="card"><h3>Needs Zach</h3><ul><li>Which first outcome syntax deserves projection?</li><li>Which async relation is worth drawing first?</li><li>What source contract, if any, earns a state region?</li><li>Should a source lens follow call-contract work?</li></ul></article><article class="card"><h3>Deliberately not done</h3><ul><li>No draggable vendor-style palette.</li><li>No universal error wire, global timeline, inferred statechart, or user-authored schema.</li><li>No mask/dialog programming or host-runtime property UI.</li><li>No SystemSketch product/schema/analyzer change.</li></ul></article></div></section><section id="sources"><div class="section-head"><div><div class="tag b">Primary only</div><h2>Numbered source index</h2></div><p>Every screenshot caption links directly to its NI, Epic, or MathWorks documentation page. The report embeds the capture so its evidence remains visible later.</p></div><ol class="sources">{source_index}</ol></section><footer>Canonical source: <code>{esc(SOURCE_NOTE.relative_to(REPO))}</code> · generated by <code>docs/build_labview_blueprint_simulink_gap_analysis.py</code> · branch <code>{esc(branch)}</code>, source base <code>{esc(base)}</code>. The durable review URL pins the exact revision. Official screenshots are embedded evidence; blue proposal diagrams are original SystemSketch grammar sketches.</footer></main>'''
